function reviewPracticeArchiveGroups(archive,ownerId){
 if(archive.ownerId!==ownerId||!Array.isArray(archive.receipts)||!Array.isArray(archive.current))throw Error('本人实践回执不一致。');const groups=new Map();
 for(const receipt of archive.receipts){const record=receipt.record;if(record?.authorId!==ownerId||record.eventId!==receipt.eventId||typeof record.id!=='string')throw Error('实践历史身份不一致。');if(!groups.has(record.id))groups.set(record.id,[]);groups.get(record.id).push(receipt)}
 return [...groups.values()].map(history=>{const latest=history.at(-1),current=archive.current.find(c=>c.record?.id===latest.record.id)?.record;if(current&&(current.authorId!==ownerId||current.eventId!==latest.eventId||JSON.stringify(current.sourceSnapshot)!==JSON.stringify(latest.record.sourceSnapshot)))throw Error('服务实践与当时知识快照不一致，原资料保留。');return {history,latest,record:current||latest.record,missing:!current}}).sort((a,b)=>Date.parse(b.record.createdAt)-Date.parse(a.record.createdAt));
}
function reviewPracticeArchiveSnapshot(receipt){
 const k=receipt.record.sourceSnapshot,a=receipt.activitySnapshot;if(!k||typeof k.nodeTitle!=='string'||typeof k.nodeGoal!=='string'||!a||!Number.isFinite(a.startedAt)||!Number.isFinite(a.endedAt)||!Array.isArray(a.segments)||a.segments.some(p=>!Number.isFinite(p.start)||!Number.isFinite(p.end)||p.start<a.startedAt||p.end<p.start||p.end>a.endedAt))throw Error('当时目标或活动时间无法核对，原资料保留。');const elapsed=a.segments.reduce((sum,p)=>sum+p.end-p.start,0);
 return `<p class="pre small">当时目标：${esc(k.nodeTitle)} · v${esc(k.nodeVersion)}<br>${esc(k.nodeGoal)}</p><p class="pre small">${k.methodId===null?'独立尝试':`当时方法：${esc(k.methodTitle)} · ${esc(k.methodAuthor||'作者未记录')} · ${esc(k.serviceReference?.version||k.version)}`}<br>${esc(k.content||'')}<br>起步：${esc(k.five||'')}</p><p class="small muted">实际活动 ${clock(elapsed)} · ${a.segments.length} 段<br>${esc(dt(a.startedAt))} → ${esc(dt(a.endedAt))}</p>${(k.resourceLinks||[]).map(reviewResourceLink).join('')}`;
}
function reviewPracticeRecordBody(record){return `<p class="pre">${esc(record.text||'')}</p>${(record.images||[]).map((p,i)=>`<p class="small"><a href="/api/media/${encodeURIComponent(p.id)}" target="_blank" rel="noopener noreferrer">查看原记录图片 ${i+1}</a></p>`).join('')}`}
async function reviewOpenOwnedPractices(){
 const context=reviewContext();modal('<h2>本人服务实践与历史</h2><p class="small muted">按当时保存的知识、方法和实际活动段查看。旧记录缺失快照时单独标明，不用现在的目标补造。</p><p id="own-practice-status" role="status">正在核对本人实践…</p><div id="own-practice-results"></div><button id="own-practice-retry" class="ghost" hidden>重新读取本人实践</button>','','本人实践历史');const host=document.getElementById('own-practice-results'),status=document.getElementById('own-practice-status'),retry=document.getElementById('own-practice-retry');let generation=0;
 async function load(){const requestGeneration=++generation;host.innerHTML='';retry.hidden=true;status.textContent='正在核对本人实践…';try{const [archive,legacy]=await Promise.all([reviewKnowledgeRequest('/api/review-practices',{context}),reviewKnowledgeRequest('/api/records',{context})]);if(!host.isConnected||!reviewContextCurrent(context)||requestGeneration!==generation)return;if(!Array.isArray(legacy.records))throw Error('原服务记录无法核对。');const groups=reviewPracticeArchiveGroups(archive,context.ownerId),bound=new Set(groups.map(g=>g.record.id)),unbound=legacy.records.filter(r=>r.authorId===context.ownerId&&!bound.has(r.id));const rendered=groups.map(g=>`<article class="list-row"><h3>${esc(g.latest.record.sourceSnapshot.nodeTitle)}</h3><p class="small muted">${g.record.lightUp?(g.missing?'历史保存时为本人自证':'服务当前记录为本人自证'):'尚未确认点亮'} · ${g.record.visibility==='public'?'原保存范围：公开':'私人保存'}${g.missing?' · 当前记录不可读，显示保存历史':''}</p><details class="saved-notes"><summary>查看当时知识与实践</summary>${reviewPracticeArchiveSnapshot(g.latest)}${reviewPracticeRecordBody(g.record)}</details><details class="saved-notes"><summary>保存历史（${g.history.length} 次）</summary>${g.history.map(r=>`<section class="list-row"><p class="small muted">${esc(r.record.updatedAt||r.record.createdAt)} · ${r.record.lightUp?'当时本人自证':'当时草稿'} · ${r.record.visibility==='public'?'当时公开选择':'当时私人保存'}</p>${reviewPracticeArchiveSnapshot(r)}${reviewPracticeRecordBody(r.record)}</section>`).join('')}</details>${S.events.some(e=>e.id===g.latest.eventId)?`<button class="ghost" data-own-practice-event="${esc(g.latest.eventId)}">查看对应事件与笔记</button>`:''}</article>`).join('');status.textContent=`${groups.length} 条已保存知识实践，${unbound.length} 条未核对完整快照的旧记录。`;host.innerHTML=rendered+(unbound.length?`<details class="saved-notes"><summary>旧版服务记录（${unbound.length} 条）</summary>${unbound.map(r=>`<article class="list-row"><h3>旧版记录</h3><p class="small muted">${esc(r.createdAt)} · 未核对完整目标与活动段<br>原节点标识：${esc(r.treeId)} / ${esc(r.nodeId)}</p>${reviewPracticeRecordBody(r)}</article>`).join('')}</details>`:'')||'<p class="small muted">本人尚未保存服务知识实践，原事件仍可在事件记录中查看。</p>';host.querySelectorAll('[data-own-practice-event]').forEach(b=>b.addEventListener('click',()=>{if(b.isConnected&&reviewContextCurrent(context)){const id=b.dataset.ownPracticeEvent;if(S.events.some(e=>e.id===id)){closeModal();handle('event-detail:'+id)}}}));
 }catch(e){if(host.isConnected&&reviewContextCurrent(context)&&requestGeneration===generation){host.innerHTML='';status.textContent=e instanceof TypeError?'实践读取未确认，原事件与笔记保留，请重新读取。':e.message;retry.hidden=false}}}
 retry.addEventListener('click',load);await load();
}
